namespace Global {

int size;

};

auto Now() {
  return std::chrono::high_resolution_clock::now();
}

struct Timer {
  Timer() : start(Now()) {}

  double GetTime() const {
    return std::chrono::duration<double>(Now() - start).count();
  }

  const decltype(Now()) start;
};

class Random {
 public:
  constexpr explicit Random(std::int64_t seed) {
    state_[0] = seed;
    state_[1] = RotateLeft(seed, 11);
    for (int i = 0; i < 16; ++i) {
      Next();
    }
  }

  constexpr double Canonical() {
    return 0x1.p-64 * Next();
  }

  constexpr int Range(int size) {
    return Next() % size;
  }

  constexpr int MinMax(int min, int max) {
    return Range(max - min + 1) + min;
  }

  template <typename V>
  void Shuffle(V& vector) {
    const int N = vector.size();
    for (int i = N - 1; i > 0; --i) {
      std::swap(vector[i], vector[Range(i + 1)]);
    }
  }

  constexpr std::uint64_t Next() {
    auto [s0, s1] = state_;
    const auto result = RotateLeft(s0 * 5, 7) * 9;
    s1 ^= s0;
    state_[0] = RotateLeft(s0, 24) ^ s1 ^ (s1 << 16);
    state_[1] = RotateLeft(s1, 37);
    return result;
  }

 private:
  static constexpr std::uint64_t RotateLeft(std::uint64_t x, int n) {
    return (x << n) | (x >> (64 - n));
  }

  std::uint64_t state_[2] = {};
};

constexpr auto CreateZobristTable() {
  std::array<std::array<std::uint64_t, kBoardSize * kBoardSize>, 17> table = {};
  Random random(1);
  for (int i = 0; i < 17; ++i) {
    for (int j = 0; j < kBoardSize * kBoardSize; ++j) {
      table[i][j] = random.Next();
    }
  }
  return table;
}

constexpr auto kZobristTable = CreateZobristTable();

int ManhattanDistance(int a, int b) {
  const int ya = a / kBoardSize;
  const int xa = a % kBoardSize;
  const int yb = b / kBoardSize;
  const int xb = b % kBoardSize;
  return std::abs(ya - yb) + std::abs(xa - xb);
}

template <typename State>
std::optional<std::string> BeamSearch(const State& initial_state,
                                      std::size_t beam_width) {
  std::unordered_set<std::uint64_t> seen;
  seen.insert(initial_state.hash);
  std::deque<std::vector<typename State::Preview>> beam(1);
  std::deque<State> pool;
  for (auto&& preview : initial_state.EnumerateNextMoves()) {
    seen.insert(std::get<2>(preview));
    beam[0].push_back(std::move(preview));
  }
  for (int time = 1; time; ++time) {
    if (time > 1000 || beam[time - 1].empty()) {
      return std::nullopt;
    }
    std::vector<typename State::Preview> candidates;
    for (const auto& preview : beam[time - 1]) {
      pool.emplace_back(preview);
      if (pool.back().IsGoal()) {
        return pool.back().ReconstructMoves();
      }
      for (auto&& next_preview : pool.back().EnumerateNextMoves()) {
        candidates.push_back(std::move(next_preview));
      }
    }
    std::sort(candidates.begin(), candidates.end());
    beam.emplace_back();
    beam[time].reserve(beam_width);
    for (auto&& preview : candidates) {
      const auto& [estimate, move, hash, previous] = preview;
      if (seen.count(hash)) continue;
      seen.insert(hash);
      beam[time].push_back(std::move(preview));
      if (beam[time].size() == beam_width) break;
    }
  }
  return std::nullopt;
}

struct Range {
  int top = 1;
  int bottom = Global::size;
  int left = 1;
  int right = Global::size;
  int row = -1;
  int column = -1;

  bool Contains(int index) const {
    const int y = index / kBoardSize;
    const int x = index % kBoardSize;
    return top <= y && y <= bottom && left <= x && x <= right;
  }
};

struct SearchStateSide {
 public:
  using Preview = std::tuple<int, int, std::uint64_t, const SearchStateSide*>;

  SearchStateSide(const std::vector<std::uint8_t>& current_tiles,
                  const std::vector<std::uint8_t>& target_tiles,
                  const Range& target_range) : range(target_range) {
    for (int y = 1; y <= Global::size; ++y) {
      for (int x = 1; x <= Global::size; ++x) {
        const int index = kBoardSize * y + x;
        if (current_tiles[index] == 0) {
          space = index;
        }
      }
    }
    if (range.row >= 0) {
      for (int x = range.left; x <= range.right; ++x) {
        positions.emplace_back(kBoardSize * range.row + x, -1);
      }
    } else {
      for (int y = range.top; y <= range.bottom; ++y) {
        positions.emplace_back(kBoardSize * y + range.column, -1);
      }
    }

    for (auto& [target, current] : positions) {
      const auto& tile = target_tiles[target];
      int best_distance = 2 * kBoardSize;
      for (int y = range.top; y <= range.bottom; ++y) {
        for (int x = range.left; x <= range.right; ++x) {
          const int index = kBoardSize * y + x;
          if (current_tiles[index] != tile) continue;
          const auto distance = ManhattanDistance(target, index);
          if (distance >= best_distance) continue;
          bool available = true;
          for (const auto& [other_target, other_current] : positions) {
            if (other_current == index) {
              available = false;
              break;
            }
          }
          if (!available) continue;
          best_distance = distance;
          current = index;
        }
      }
    }

    estimate = Evaluate(space, positions);

    hash = kZobristTable[positions.size()][space];
    for (std::size_t i = 0; i < positions.size(); ++i) {
      hash += kZobristTable[i][positions[i].second];
    }
  }

  SearchStateSide(const Preview& preview) {
    int d;
    std::tie(estimate, d, hash, previous) = preview;
    move = kMoves[d];
    range = previous->range;
    positions = previous->positions;
    const int next = previous->space + kDeltas[d];
    std::size_t index = positions.size();
    for (std::size_t i = 0; i < positions.size(); ++i) {
      if (positions[i].second == next) {
        index = i;
        break;
      }
    }
    if (index < positions.size()) {
      positions[index].second = previous->space;
    }
    space = next;

    std::uint64_t h = kZobristTable[positions.size()][space];
    for (std::size_t i = 0; i < positions.size(); ++i) {
      h += kZobristTable[i][positions[i].second];
    }
  }

  static int Evaluate(int space, const std::vector<std::pair<std::uint8_t, std::uint8_t>>& positions) {
    int sum = 0;
    for (const auto& [target, current] : positions) {
      const int distance = ManhattanDistance(target, current);
      sum += distance + 2 * std::max(0, distance - 2);
    }
    if (sum > 0) {
      int min = 2 * kBoardSize;
      for (std::size_t i = 0; i < positions.size(); ++i) {
        const auto& [target, current] = positions[i];
        if (current == target) continue;
        min = std::min(min, ManhattanDistance(current, space) - 1);
        const bool left = i == 0 || positions[i - 1].second == positions[i - 1].first;
        const bool right = i + 1 == positions.size() || positions[i + 1].second == positions[i + 1].first;
        if (left & right) {
          sum += 2;
        }
      }
      sum += (min + 1) / 2;
    }
    return 2 * sum;
  }

  std::vector<Preview> EnumerateNextMoves() const {
    auto pos = positions;
    std::vector<Preview> next_moves;
    for (int d = 0; d < 4; ++d) {
      if (kMoves[d ^ 2] == move) continue;
      const int next = space + kDeltas[d];
      if (!range.Contains(next)) continue;
      std::size_t index = positions.size();
      for (std::size_t i = 0; i < pos.size(); ++i) {
        if (pos[i].second == next) {
          index = i;
          break;
        }
      }
      auto next_hash = hash;
      next_hash += kZobristTable[pos.size()][next] - kZobristTable[pos.size()][space];
      if (index < pos.size()) {
        next_hash += kZobristTable[index][space] - kZobristTable[index][pos[index].second];
        pos[index].second = space;
      }
      next_moves.emplace_back(Evaluate(next, pos), d, next_hash, this);
      if (index < pos.size()) {
        pos[index].second = next;
      }
    }
    return next_moves;
  }

  std::string ReconstructMoves() const {
    std::string moves;
    for (const auto* state = this; state->move; state = state->previous) {
      moves.push_back(state->move);
    }
    return moves;
  }

  bool IsGoal() const {
    return estimate == 0;
  }

  bool operator<(const SearchStateSide& other) const {
    return estimate < other.estimate;
  }

  const SearchStateSide* previous = nullptr;
  std::vector<std::pair<std::uint8_t, std::uint8_t>> positions;
  Range range;
  std::uint64_t hash = 0;
  int space = -1;
  int estimate = 0;
  char move = '\0';
};

struct SearchState4x4 {
 public:
  using Preview = std::tuple<int, int, std::uint64_t, const SearchState4x4*>;

  SearchState4x4(const std::vector<std::uint8_t>& current_tiles,
                 const std::vector<std::uint8_t>& target_tiles,
                 const Range& target_range, Random& rng) {
    std::vector<std::vector<int>> current(16);
    std::vector<std::vector<int>> target(16);
    missing_tile = -1;
    for (int i = 0; i < 4; ++i) {
      const int y = target_range.top + i;
      for (int j = 0; j < 4; ++j) {
        const int x = target_range.left + j;
        const int index = 4 * i + j;
        const int board_index = kBoardSize * y + x;
        current[current_tiles[board_index]].push_back(index);
        target[target_tiles[board_index]].push_back(index);
        if (target_tiles[board_index] == 0) {
          missing_tile = index + 1;
        }
      }
    }
    table.resize(4);
    for (int u = 0; u < 2; ++u) {
      for (int v = 0; v < 2; ++v) {
        int table_index = 4;
        for (int i = 0; i < 2; ++i) {
          for (int j = 0; j < 2; ++j) {
            const int tile = 4 * (2 * u + i) + (2 * v + j) + 1;
            if (tile == missing_tile) {
              table_index = 2 * i + j;
            }
          }
        }
        if (table_index < 4) {
          table[2 * u + v] = kPatternDatabase3[2 * u + v][table_index];
        } else {
          table[2 * u + v] = kPatternDatabase4[2 * u + v];
        }
      }
    }

    constexpr int kInfinity = std::numeric_limits<int>::max() / 2;
    estimate = kInfinity;
    for (int trial = 0; trial < 10; ++trial) {
      std::vector<std::uint8_t> board(16);
      for (int i = 1; i < 16; ++i) {
        if (current[i].empty()) continue;
        if (current[i].size() > 1) {
          rng.Shuffle(current[i]);
        }
        for (std::size_t j = 0; j < current[i].size(); ++j) {
          board[current[i][j]] = target[i][j] + 1;
        }
      }
      if (!IsSolvable(board)) continue;
      std::vector<std::uint8_t> pos(17);
      for (std::size_t i = 0; i < board.size(); ++i) {
        pos[board[i]] = i;
      }
      if (const auto value = Evaluate(pos); value < estimate) {
        estimate = value;
        tiles.swap(board);
        positions.swap(pos);
      }
    }
    if (estimate == kInfinity) {
      feasible = false;
    }
    hash = 0;
    for (std::size_t i = 0; i < positions.size(); ++i) {
      hash += kZobristTable[i][positions[i]];
    }
  }

  SearchState4x4(const Preview& preview) {
    int d;
    std::tie(estimate, d, hash, previous) = preview;
    move = kMoves[d];
    tiles = previous->tiles;
    positions = previous->positions;
    const int next = adjacent[positions[0]][d];
    std::swap(tiles[positions[0]], tiles[next]);
    std::swap(positions[0], positions[tiles[positions[0]]]);
    table = previous->table;
    missing_tile = previous->missing_tile;

    std::uint64_t h = 0;
    for (std::size_t i = 0; i < positions.size(); ++i) {
      h += kZobristTable[i][positions[i]];
    }
  }

  int Evaluate(const std::vector<std::uint8_t>& pos) const {
    int sum = -4 * 'A';
    for (int u = 0; u < 2; ++u) {
      for (int v = 0; v < 2; ++v) {
        int index = 0;
        for (int i = 0; i < 2; ++i) {
          for (int j = 0; j < 2; ++j) {
            const int tile = 4 * (2 * u + i) + (2 * v + j) + 1;
            if (tile == missing_tile) continue;
            index = (index << 4) | pos[tile];
          }
        }
        sum += table[2 * u + v][index];
      }
    }

    int row[4];
    for (int t = 0; t < 2; ++t) {
      const int stride = t == 0 ? 4 : 1;
      const int delta = 5 - stride;
      for (int y = 0; y < 4; ++y) {
        for (int x = 0; x < 4; ++x) {
          row[x] = stride * y + delta * x;
        }
        int counts[2] = {};
        for (int i = 0; i < 2; ++i) {
          for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
              counts[i] += pos[row[2 * i + j] + 1] == row[2 * (1 - i) + k];
            }
          }
        }
        sum += 2 * std::min(counts[0], counts[1]);
      }
    }
    return sum;
  }

  bool IsSolvable(std::vector<std::uint8_t> board) const {
    const auto space = std::find(board.begin(), board.end(), 0);
    const auto space_index = space - board.begin();
    *space = missing_tile;
    bool solvable = (space_index ^ missing_tile ^
                     (space_index >> 2) ^ ((missing_tile- 1) >> 2)) & 1;
    for (int i = 0; i < 16; ++i) {
      for (int j = 0; j < i; ++j) {
        solvable ^= board[i] < board[j];
      }
    }
    return solvable;
  }

  std::vector<Preview> EnumerateNextMoves() const {
    auto pos = positions;
    std::vector<Preview> next_moves;
    for (int d = 0; d < 4; ++d) {
      if (kMoves[d ^ 2] == move) continue;
      const int next = adjacent[positions[0]][d];
      if (next < 0) continue;
      auto next_hash = hash;
      next_hash -= kZobristTable[0][pos[0]] + kZobristTable[tiles[next]][pos[tiles[next]]];
      std::swap(pos[0], pos[tiles[next]]);
      next_hash += kZobristTable[0][pos[0]] + kZobristTable[tiles[next]][pos[tiles[next]]];
      next_moves.emplace_back(Evaluate(pos), d, next_hash, this);
      std::swap(pos[0], pos[tiles[next]]);
    }
    return next_moves;
  }

  std::string ReconstructMoves() const {
    std::string moves;
    for (const auto* state = this; state->move; state = state->previous) {
      moves.push_back(state->move);
    }
    return moves;
  }

  bool IsGoal() const {
    return estimate == 0;
  }

  bool operator<(const SearchState4x4& other) const {
    return estimate < other.estimate;
  }

  static void Initialize() {
    adjacent.resize(16);
    for (int y = 0; y < 4; ++y) {
      for (int x = 0; x < 4; ++x) {
        const int index = 4 * y + x;
        adjacent[index].assign(4, -1);
        for (int d = 0; d < 4; ++d) {
          const auto& [dy, dx] = kDirections[d];
          const int y1 = y + dy;
          const int x1 = x + dx;
          if (y1 < 0 || y1 >= 4 || x1 < 0 || x1 >= 4) continue;
          adjacent[index][d] = 4 * y1 + x1;
        }
      }
    }
  }

  const SearchState4x4* previous = nullptr;
  std::vector<std::uint8_t> tiles;
  std::vector<std::uint8_t> positions;
  std::vector<const char*> table;
  std::uint64_t hash = 0;
  int missing_tile = -1;
  int estimate = 0;
  char move = '\0';
  bool feasible = true;

  static std::vector<std::vector<int>> adjacent;
};

std::vector<std::vector<int>> SearchState4x4::adjacent;

struct Board {
  Board(const std::vector<std::uint8_t>& tiles) : current_tiles(tiles) {
    for (int y = range.top; y <= range.bottom; ++y) {
      for (int x = range.left; x <= range.right; ++x) {
        const int index = kBoardSize * y + x;
        if (tiles[index] == 0) {
          space = index;
        }
      }
    }
  }

  Board(const Board* prev) :
      space(prev->space), cost(prev->cost),
      range(prev->range), previous(prev), current_tiles(prev->current_tiles) {}

  void Advance(std::string moves) {
    cost += moves.size();
    estimate = 0;
    moves_from_previous = moves;
    std::reverse(moves.begin(), moves.end());
    for (const auto& move : moves) {
      for (int d = 0; d < 4; ++d) {
        if (kMoves[d] == move) {
          const int next = space + kDeltas[d];
          std::swap(current_tiles[space], current_tiles[next]);
          space = next;
          break;
        }
      }
    }
  }

  bool Search() {
    if (estimate == 0) {
      return true;
    }
    if (search_state_4x4) {
      if (!search_state_4x4->feasible) {
        return false;
      }
      const auto moves = BeamSearch(*search_state_4x4, 400);
      if (moves.has_value()) {
        Advance(moves.value());
        estimate = 0;
        return true;
      }
    }
    if (search_state_side) {
      const auto moves = BeamSearch(*search_state_side, 200);
      if (moves.has_value()) {
        Advance(moves.value());
        if (range.row >= 0) {
          if (range.row == range.top) {
            ++range.top;
          } else {
            --range.bottom;
          }
        } else {
          if (range.column == range.left) {
            ++range.left;
          } else {
            --range.right;
          }
        }
        estimate = 0;
        return true;
      }
    }
    return false;
  }

  auto GenerateTargets(Random& rng, int num_trials) const {
    std::vector<int> constraints(16);
    std::vector<std::tuple<int, int, int, int>> edges;
    for (int y = 1; y <= Global::size; ++y) {
      for (int x = 1; x <= Global::size; ++x) {
        const int index = kBoardSize * y + x;
        ++constraints[current_tiles[index]];
        if (!range.Contains(index)) continue;
        if (const int next = index - 1; range.Contains(next)) {
          edges.emplace_back(index, next, 1 << 0, 1 << 2);
        }
        if (const int next = index - kBoardSize; range.Contains(next)) {
          edges.emplace_back(index, next, 1 << 1, 1 << 3);
        }
      }
    }
    const auto compute_hash = [&](const auto& tiles) {
      std::uint64_t hash = 0;
      for (int y = 1; y <= Global::size; ++y) {
        for (int x = 1; x <= Global::size; ++x) {
          const int index = kBoardSize * y + x;
          hash += kZobristTable[tiles[index]][index];
        }
      }
      return hash;
    };
    std::vector<std::vector<std::uint8_t>> targets;
    std::unordered_set<std::uint64_t> seen;
    atcoder::dsu initial_dsu(kBoardSize * kBoardSize);
    auto initial_target = target_tiles;
    int default_reserved = kBoardSize * Global::size + Global::size;
    if (!target_tiles.empty()) {
      targets.push_back(target_tiles);
      seen.insert(compute_hash(target_tiles));
      for (const auto& [a, b, line_a, line_b] : edges) {
        initial_target[a] &= ~line_a;
        initial_target[b] &= ~line_b;
      }
      for (int y = 1; y <= Global::size; ++y) {
        for (int x = 1; x <= Global::size; ++x) {
          const int index = kBoardSize * y + x;
          for (int d = 0; d < 2; ++d) {
            const int next = index + kDeltas[d];
            if ((initial_target[index] >> d) &
                (initial_target[next] >> (d ^ 2)) & 1) {
              initial_dsu.merge(index, next);
            }
          }
          if (target_tiles[index] == 0) {
            default_reserved = index;
          }
        }
      }
    } else {
      initial_target.resize(kBoardSize * kBoardSize);
    }
    for (int trial = 0; targets.empty() || trial < num_trials; ++trial) {
      auto dsu = initial_dsu;
      auto target = initial_target;
      int reserved = default_reserved;
      if (rng.Range(2)) {
        const int y = rng.MinMax(range.top, range.bottom);
        const int x = rng.MinMax(range.left, range.right);
        reserved = kBoardSize * y + x;
      }
      rng.Shuffle(edges);
      for (const auto& [a, b, line_a, line_b] : edges) {
        if (a == reserved || b == reserved || dsu.same(a, b)) continue;
        dsu.merge(a, b);
        target[a] |= line_a;
        target[b] |= line_b;
      }
      std::vector<int> counts(16);
      for (int y = 1; y <= Global::size; ++y) {
        for (int x = 1; x <= Global::size; ++x) {
          const int index = kBoardSize * y + x;
          ++counts[target[index]];
        }
      }
      const auto compute_score = [&]() {
        int score = 0;
        for (int i = 1; i < 16; ++i) {
          score -= std::abs(counts[i] - constraints[i]);
        }
        return score;
      };
      int score = compute_score();
      for (int iter = 0; score < 0 && iter < 1000; ++iter) {
        std::tuple<int, int, int, int> removed, added;
        const auto toggle = [&](const auto& edge) {
          const auto& [a, b, line_a, line_b] = edge;
          --counts[target[a]];
          --counts[target[b]];
          ++counts[target[a] ^= line_a];
          ++counts[target[b] ^= line_b];
        };
        for (std::size_t i = 0; i < edges.size(); ++i) {
          const std::size_t j = i + rng.Range(edges.size() - i);
          std::swap(edges[i], edges[j]);
          const auto& [a, b, line_a, line_b] = edges[i];
          if ((target[a] & line_a) &&
              (counts[target[a]] > constraints[target[a]] ||
               counts[target[b]] > constraints[target[b]])) {
            toggle(removed = edges[i]);
            break;
          }
        }
        dsu = initial_dsu;
        for (const auto& [a, b, line_a, line_b] : edges) {
          if (target[a] & line_a) {
            dsu.merge(a, b);
          }
        }
        for (std::size_t i = 0; i < edges.size(); ++i) {
          const std::size_t j = i + rng.Range(edges.size() - i);
          std::swap(edges[i], edges[j]);
          const auto& [a, b, line_a, line_b] = edges[i];
          if (a != reserved && b != reserved &&
              !(target[a] & line_a) && !dsu.same(a, b)) {
            toggle(added = edges[i]);
            break;
          }
        }
        if (const int next_score = compute_score(); next_score >= score) {
          score = next_score;
        } else {
          toggle(added);
          toggle(removed);
        }
      }
      if (score == 0) {
        const auto hash = compute_hash(target);
        if (seen.count(hash)) continue;
        seen.insert(hash);
        targets.push_back(target);
      }
    }
    return targets;
  }

  std::vector<Board> GenerateNextBoards(Random& rng, int num_trials) {
    std::vector<Board> boards;
    for (auto&& targets : GenerateTargets(rng, num_trials)) {
      if (range.top + 3 == range.bottom && range.left + 3 == range.right) {
        Board next(this);
        next.target_tiles.swap(targets);
        next.search_state_4x4.reset(
            new SearchState4x4(current_tiles, next.target_tiles, range, rng));
        next.estimate = next.search_state_4x4->estimate;
        boards.push_back(std::move(next));
      } else {
        int next_space_y = -1;
        int next_space_x = -1;
        for (int y = range.top; y <= range.bottom; ++y) {
          for (int x = range.left; x <= range.right; ++x) {
            if (targets[kBoardSize * y + x] == 0) {
              next_space_y = y;
              next_space_x = x;
            }
          }
        }
        if (range.top + 3 < range.bottom) {
          for (const int row : {range.top, range.bottom}) {
            if (row == next_space_y) continue;
            Board next(this);
            next.range.row = row;
            next.range.column = -1;
            next.target_tiles = targets;
            next.search_state_side.reset(
                new SearchStateSide(current_tiles, targets, next.range));
            next.estimate = next.search_state_side->estimate;
            boards.push_back(std::move(next));
          }
        }
        if (range.left + 3 < range.right) {
          for (const int column : {range.left, range.right}) {
            if (column == next_space_x) continue;
            Board next(this);
            next.range.row = -1;
            next.range.column = column;
            next.target_tiles = targets;
            next.search_state_side.reset(
                new SearchStateSide(current_tiles, targets, next.range));
            next.estimate = next.search_state_side->estimate;
            boards.push_back(std::move(next));
          }
        }
      }
    }
    return boards;
  }

  std::string ReconstructMoves() const {
    std::string moves;
    for (auto board = this; board; board = board->previous) {
      moves += board->moves_from_previous;
    }
    std::reverse(moves.begin(), moves.end());
    return moves;
  }

  bool operator<(const Board& other) const {
    return cost + estimate < other.cost + other.estimate;
  }

  int space = 0;
  int cost = 0;
  int estimate = 0;
  Range range;
  const Board* previous = nullptr;
  std::string moves_from_previous;
  std::vector<std::uint8_t> current_tiles;
  std::vector<std::uint8_t> target_tiles;
  std::unique_ptr<SearchStateSide> search_state_side;
  std::unique_ptr<SearchState4x4> search_state_4x4;
};

struct Comparer {
  template <typename T>
  bool operator()(const T* a, const T* b) const {
    return *b < *a;
  }
};

class Solver {
 public:
  explicit Solver(int N) {
    Global::size = N;
    SearchState4x4::Initialize();
  }

  std::string Solve(const std::vector<std::uint8_t>& tiles) {
    Timer timer;
    const std::size_t num_generations = (Global::size - 4) * 2;
    Random rng(1);
    std::deque<Board> state_pool;
    std::vector<std::priority_queue<Board*, std::vector<Board*>,
                                    Comparer>> beam(num_generations + 1);
    Board initial_board(tiles);
    for (auto&& next : initial_board.GenerateNextBoards(rng, 100)) {
      state_pool.push_back(std::move(next));
      beam[0].push(&state_pool.back());
    }

    int best_cost = std::numeric_limits<int>::max();
    std::string best_moves;
    for (int trial = 0; ; ++trial) {
      for (std::size_t g = 0; g <= num_generations; ++g) {
        if (timer.GetTime() > 0.95 * kTimeLimit) {
          return best_moves;
        }
        if (beam[g].empty()) continue;
        const auto board = beam[g].top();
        beam[g].pop();
        const std::size_t gen = 2 * Global::size - 2 - (board->range.bottom - board->range.top) - (board->range.right - board->range.left);
        if (gen != g) continue;
        if (!board->Search()) continue;
        if (g == num_generations) {
          if (board->cost < best_cost) {
            best_cost = board->cost;
            best_moves = board->ReconstructMoves();
          }
        } else {
          for (auto&& next : board->GenerateNextBoards(rng, 20)) {
            state_pool.push_back(std::move(next));
            beam[g + 1].push(&state_pool.back());
          }
        }
      }
    }
    return best_moves;
  }
};

int main() {
  int N, T;
  std::cin >> N >> T;
  std::vector<std::uint8_t> tiles(kBoardSize * kBoardSize);
  for (int y = 0; y < N; ++y) {
    std::string row;
    std::cin >> row;
    for (int x = 0; x < N; ++x) {
      if (std::isdigit(row[x])) {
        tiles[kBoardSize * (y + 1) + (x + 1)] = row[x] - '0';
      } else {
        tiles[kBoardSize * (y + 1) + (x + 1)] = row[x] - 'a' + 10;
      }
    }
  }

  Solver solver(N);
  std::cout << solver.Solve(tiles) << std::endl;

  return 0;
}
